while count is not 0:
    if count is 10:
        say "10"
    else if count is 8:
        say "8"
    else if count is 6:
        say "6"
    else if count is 4:
        say "4"
    else if count is 2:
        say "2"
    else if count is 0:
        say "0"
    count = count - 2
say "Blast off!"
```

